              for (let a = 0, b = p.length - 1; a < p.length; b = a++) {
                if (segsIntersect(x1, z1, x2, z2, p[b][0], p[b][1], p[a][0], p[a][1])) return false;
              }
              if (pointInPoly(x1, z1, p) || pointInPoly(x2, z2, p)) return false;
