              pole.position.set(ux, 1.15, 1.35);
              g.add(pole);
              const tbl = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.55, 0.08, 10), patioWoodMat);
              tbl.position.set(ux, 0.78, 1.35);
