      addBuilding(rotRect(-738, 316, 16, 16), 230, 'condo', 20.0, { tint: [0.95, 1.02, 1.12], shops: false });
      addBuilding(rotRect(-694, 316, 16, 16), 255, 'condo', 20.0, { tint: [0.95, 1.02, 1.12], shops: false });
      roofLights.push(new THREE.Vector3(-738, 232, 316), new THREE.Vector3(-694, 257, 316));

