    rotatingRestaurantRing.add(f3RotateFloor);

    // 16 Dining Table Settings placed radially along the revolving ring using InstancedMesh (5 draw calls total)
    const tableInst = new THREE.InstancedMesh(new THREE.CylinderGeometry(1.2, 1.25, 0.76, 16), whiteLinenMat, 16);
    const lampInst = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.06, 0.08, 0.22, 8), amberCandleMat, 16);
    const seatInst = new THREE.InstancedMesh(new THREE.BoxGeometry(0.55, 0.12, 0.55), burgundyCarpetMat, 64);
    const backInst = new THREE.InstancedMesh(new THREE.BoxGeometry(0.55, 0.55, 0.08), woodFloorMat, 64);

    const tmpInstM = new THREE.Matrix4();
    const tmpInstPos = new THREE.Vector3();
    const tmpInstQuat = new THREE.Quaternion();
    const tmpInstScale = new THREE.Vector3(1, 1, 1);
    const tmpEuler = new THREE.Euler();

    let chairIdx = 0;
    for (let t = 0; t < 16; t++) {
      const ta = (t * Math.PI * 2) / 16;
      const tr = 17.5; // mid-ring dining radius
      const tx = Math.cos(ta) * tr;
      const tz = Math.sin(ta) * tr;
      const troty = -ta + Math.PI / 2;

      // Table
      tmpEuler.set(0, troty, 0);
      tmpInstQuat.setFromEuler(tmpEuler);
      tmpInstPos.set(tx, 0.38, tz);
      tmpInstM.compose(tmpInstPos, tmpInstQuat, tmpInstScale);
      tableInst.setMatrixAt(t, tmpInstM);

      // Lamp
      tmpInstPos.set(tx, 0.86, tz);
      tmpInstM.compose(tmpInstPos, tmpInstQuat, tmpInstScale);
      lampInst.setMatrixAt(t, tmpInstM);

      // 4 Chairs around table
      const chairOffsets = [
        [0, -1.2, 0], [0, 1.2, Math.PI],
        [-1.2, 0, -Math.PI / 2], [1.2, 0, Math.PI / 2]
      ];
      chairOffsets.forEach(([cx, cz, crot]) => {
        const cosT = Math.cos(troty), sinT = Math.sin(troty);
        const wcx = tx + (cx * cosT + cz * sinT);
        const wcz = tz + (-cx * sinT + cz * cosT);
        const chairRot = troty + crot;

        tmpEuler.set(0, chairRot, 0);
        tmpInstQuat.setFromEuler(tmpEuler);

        // Seat
        tmpInstPos.set(wcx, 0.44, wcz);
        tmpInstM.compose(tmpInstPos, tmpInstQuat, tmpInstScale);
        seatInst.setMatrixAt(chairIdx, tmpInstM);

        // Back
        const cosC = Math.cos(chairRot), sinC = Math.sin(chairRot);
        const bcz = -0.24;
        const wbx = wcx + bcz * sinC;
        const wbz = wcz + bcz * cosC;
        tmpInstPos.set(wbx, 0.72, wbz);
        tmpInstM.compose(tmpInstPos, tmpInstQuat, tmpInstScale);
        backInst.setMatrixAt(chairIdx, tmpInstM);

        chairIdx++;
      });
    }

    tableInst.instanceMatrix.needsUpdate = true;
    lampInst.instanceMatrix.needsUpdate = true;
    seatInst.instanceMatrix.needsUpdate = true;
    backInst.instanceMatrix.needsUpdate = true;

