      // ---------- F. TORONTO ISLANDS IN THE DISTANCE (Billy Bishop Airport, Centre Island, Ward's Island) ----------
      // Uses fog: false so the islands, trees, lighthouse, Ferris wheel & runway lights remain crisp across the harbour!
      const islandLandMat = new THREE.MeshBasicMaterial({ color: 0x143824, fog: false });
      const islandSandMat = new THREE.MeshBasicMaterial({ color: 0xd6bf90, fog: false });
      const islandTreeMat1 = new THREE.MeshBasicMaterial({ color: 0x166534, fog: false });
      const islandTreeMat2 = new THREE.MeshBasicMaterial({ color: 0x15803d, fog: false });
      const islandStoneMat = new THREE.MeshBasicMaterial({ color: 0xf1f5f9, fog: false });
      const islandRedMat = new THREE.MeshBasicMaterial({ color: 0xdc2626, fog: false });
      const islandGoldMat = new THREE.MeshBasicMaterial({ color: 0xfacc15, fog: false });
      const islandCyanMat = new THREE.MeshBasicMaterial({ color: 0x38bdf8, fog: false });
      const runwayMat = new THREE.MeshBasicMaterial({ color: 0x1e293b, fog: false });

      const islandsGroup = new THREE.Group();

      // Helper to build an island landmass with sandy shore & tree canopy
      function addIslandMass(cx, cz, rx, rz, rotY, treeCount) {
        const ig = new THREE.Group();
        const shore = new THREE.Mesh(new THREE.CylinderGeometry(1, 1.04, 1.4, 28), islandSandMat);
        shore.scale.set(rx + 14, 1, rz + 14);
        shore.position.y = WATER_Y + 0.5;
        ig.add(shore);

        const turf = new THREE.Mesh(new THREE.CylinderGeometry(0.96, 1, 2.8, 28), islandLandMat);
        turf.scale.set(rx, 1, rz);
        turf.position.y = WATER_Y + 1.4;
        ig.add(turf);

        for (let i = 0; i < treeCount; i++) {
          const a = hash(i * 3.1 + cx) * Math.PI * 2;
          const r = (0.15 + 0.78 * Math.sqrt(hash(i * 7.7 + cz)));
          const tx = Math.cos(a) * rx * r;
          const tz = Math.sin(a) * rz * r;
          const th = 11 + hash(i * 5.3) * 14;
          const tr = 5.5 + hash(i * 2.9) * 5.5;
          const crown = new THREE.Mesh(
            new THREE.ConeGeometry(tr, th, 7),
            i % 2 === 0 ? islandTreeMat1 : islandTreeMat2
          );
          crown.position.set(tx, WATER_Y + 2.5 + th / 2, tz);
          ig.add(crown);
        }
        ig.position.set(cx, 0, cz);
        ig.rotation.y = rotY;
        islandsGroup.add(ig);
        return ig;
      }

      // 1. West Island: Billy Bishop Toronto City Airport (YTZ) across the Western Gap (x = -880, z = 1160)
      const ytzIsland = addIslandMass(-880, 1160, 390, 150, -0.22, 48);
