        term.position.set(160, 7.5, -68);
        ytzIsland.add(term);
        const atcShaft = new THREE.Mesh(new THREE.CylinderGeometry(3.2, 4.2, 34, 12), islandStoneMat);
        atcShaft.position.set(110, 19, -58);
        ytzIsland.add(atcShaft);
        const atcCab = new THREE.Mesh(new THREE.CylinderGeometry(5.5, 4.2, 5.5, 12), islandCyanMat);
        atcCab.position.set(110, 38, -58);
        ytzIsland.add(atcCab);
        airportBeacon = new THREE.Group();
        const bBeam = new THREE.Mesh(new THREE.BoxGeometry(26, 1.4, 1.4), islandGoldMat);
        airportBeacon.add(bBeam);
        airportBeacon.position.set(110, 42.5, -58);
        ytzIsland.add(airportBeacon);
        const ytzSign = signMesh(['BILLY BISHOP TORONTO CITY AIRPORT • YTZ'], 44, 5.5, { bg: '#0f172a', fg: '#38bdf8', borderColor: '#0284c7', size: 64 });
        ytzSign.material.forEach(m => { m.fog = false; });
        ytzSign.position.set(160, 17, -82);
        ytzSign.rotation.y = Math.PI;
        ytzIsland.add(ytzSign);
