        const wSign = signMesh(["WARD'S ISLAND & RCYC"], 36, 4.8, { bg: '#1e3a8a', fg: '#ffffff', borderColor: '#38bdf8', size: 62 });
        wSign.material.forEach(m => { m.fog = false; });
